function vowelWordsInRanges(words: string[], queries: number[][]): number[] {
  const isVowel = (c: string) => "aeiou".includes(c);
  return queries.map(([l, r]) => {
    let count = 0;
    for (let i = l; i <= r; i++) if (isVowel(words[i][0]) && isVowel(words[i][words[i].length - 1])) count++;
    return count;
  });
}

