function vowelWordsInRanges(words: string[], queries: number[][]): number[] {
  const vowels = new Set(["a", "e", "i", "o", "u"]);
  const pre = new Array(words.length + 1).fill(0);
  words.forEach((w, i) => {
    pre[i + 1] = pre[i] + (vowels.has(w[0]) && vowels.has(w[w.length - 1]) ? 1 : 0);
  });
  return queries.map(([l, r]) => pre[r + 1] - pre[l]);
}

